-- Migration 006: seed the directory (25 real organizations + one opportunity each).
-- Run AFTER migration 005. Idempotent: clears prior directory rows (owner_id is
-- null) and re-inserts. User-owned orgs (owner_id set) are never touched.

delete from public.organizations where owner_id is null;

