  ('e5000000-0000-4000-8000-000000000010', null, 'Crisis Text Line', 'A free, confidential, 24/7 mental-health support line staffed by trained volunteer crisis counselors reaching people over text.', 'https://www.crisistextline.org', 'https://www.google.com/s2/favicons?domain=www.crisistextline.org&sz=128', null, 'medicine', array['training provided', 'recurring'], true, false, 18, 'United States', null, null, true, true, 'ongoing', false),
  ('e5000000-0000-4000-8000-000000000011', null, 'Be My Eyes', 'A free app that connects people who are blind or have low vision with sighted volunteers for visual help through live video.', 'https://www.bemyeyes.com', 'https://www.google.com/s2/favicons?domain=www.bemyeyes.com&sz=128', null, 'community', array['no experience needed', 'one-time'], true, true, 17, 'Global', null, null, true, true, 'ongoing', false),
  ('e5000000-0000-4000-8000-000000000012', null, 'Translators without Borders', 'Part of CLEAR Global, a nonprofit closing the language gap in humanitarian and crisis response worldwide.', 'https://translatorswithoutborders.org', 'https://www.google.com/s2/favicons?domain=translatorswithoutborders.org&sz=128', null, 'community', array['recurring'], true, true, 18, 'Global', null, null, true, true, 'ongoing', false),
