  ('e5000000-0000-4000-8000-000000000018', null, 'National Park Service', 'The federal agency caring for more than 400 national parks, monuments, and historic sites across America.', 'https://www.nps.gov', 'https://www.google.com/s2/favicons?domain=www.nps.gov&sz=128', null, 'environment', array['outdoors', 'good for crews'], false, false, 16, 'United States', null, null, true, true, 'both', false),
