  ('e5000000-0000-4000-8000-000000000020', null, 'DoSomething.org', 'One of the largest nonprofits built specifically for young people and social change, with millions of members.', 'https://www.dosomething.org', 'https://www.google.com/s2/favicons?domain=www.dosomething.org&sz=128', null, 'community', array['no experience needed', 'counts for school hours'], true, false, 13, 'United States', null, null, true, true, 'both', false),
  ('e5000000-0000-4000-8000-000000000021', null, 'Girls on the Run', 'A physical-activity based youth development program that builds confidence in girls through the power of running.', 'https://www.girlsontherun.org', 'https://www.google.com/s2/favicons?domain=www.girlsontherun.org&sz=128', null, 'sports', array['recurring'], false, false, 14, 'United States', null, null, true, true, 'both', false),
