insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('e6000000-0000-4000-8000-000000000001', 'e5000000-0000-4000-8000-000000000001', 'Become a Red Cross Volunteer', 'disaster', 'Volunteers are the heart of the Red Cross - more than 90% of the workforce is unpaid. You can help families recover after home fires and natural disasters, support blood drives that keep hospitals stocked, teach preparedness in your community, or take on virtual roles like casework and social media from home. Full training is provided, so no experience is needed to start making a real difference.', array['no experience needed', 'training provided'], 16, false, false, true, '4+ hrs / shift', 'https://www.redcross.org/volunteer/become-a-volunteer.html', 'https://www.redcross.org/volunteer/become-a-volunteer.html', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000002', 'e5000000-0000-4000-8000-000000000002', 'Volunteer at a Local Food Bank', 'food', 'Hunger exists in every county in America, and food banks rely on volunteers to move millions of pounds of food each week. Through your nearest Feeding America member bank you can sort and box donated groceries, pack weekend meal kits for kids, staff mobile pantries, or help at distribution events. Shifts are flexible, welcoming to groups, and a great way to log service hours with friends.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2-4 hrs / shift', 'https://www.feedingamerica.org/take-action/volunteer', 'https://www.feedingamerica.org/take-action/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000003', 'e5000000-0000-4000-8000-000000000003', 'Build Homes with Habitat', 'community', 'Habitat brings volunteers and future homeowners together to build affordable housing side by side. On a local build site you might frame walls, paint, or landscape, and no construction experience is required because team leaders teach you everything on site. If swinging a hammer is not your thing, Habitat ReStore resale shops also need help sorting and selling donated goods to fund the mission.', array['good for crews', 'training provided'], 16, false, false, true, 'Full day', 'https://www.habitat.org/volunteer', 'https://www.habitat.org/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000004', 'e5000000-0000-4000-8000-000000000004', 'Power Real Research Online', 'tech', 'Zooniverse lets anyone contribute to genuine scientific discovery from a laptop or phone. You might classify distant galaxies, identify animals in trail-camera photos, or transcribe historic weather logs and letters, and your work goes directly to researchers who publish real findings. There is no minimum time commitment, tasks take just minutes each, and projects publish guidance for younger volunteers.', array['no experience needed', 'one-time'], 0, true, true, true, 'Flexible', 'https://www.zooniverse.org/projects', 'https://www.zooniverse.org/projects', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000005', 'e5000000-0000-4000-8000-000000000005', 'Transcribe Smithsonian Records', 'art', 'Behind the Smithsonian are millions of handwritten documents, field notes, diaries, and specimen labels that computers cannot read. As a digital volunteer you turn those images into searchable, accessible text that researchers and the public can use. Work as little or as much as you like from home, pick projects that match your interests from science to history to art, and see your contributions become part of the permanent record.', array['no experience needed', 'one-time'], 13, true, true, true, 'Flexible', 'https://transcription.si.edu', 'https://transcription.si.edu', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000006', 'e5000000-0000-4000-8000-000000000006', 'Deliver Meals to Seniors', 'seniors', 'For many homebound older adults, a Meals on Wheels volunteer is the only person they see all day. Volunteers deliver hot meals along a local route and take a moment to check in, share a smile, and make sure their neighbor is safe and well. Routes usually take an hour or two, fit around a normal schedule, and the friendly visit means as much as the food.', array['recurring'], 16, false, false, true, '1-2 hrs / route', 'https://www.mealsonwheelsamerica.org/volunteer', 'https://www.mealsonwheelsamerica.org/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000007', 'e5000000-0000-4000-8000-000000000007', 'Be a Buddy', 'community', 'Best Buddies pairs volunteers in one-to-one friendships with people who have intellectual and developmental disabilities, and runs school and college chapters across the country. As a buddy you hang out, text, and share activities with your match, building a real friendship that changes both of your lives. Chapters welcome middle and high schoolers, and the e-Buddies program offers an online pen-pal option too.', array['no experience needed', 'recurring'], 12, false, false, true, '1-2 hrs / week', 'https://www.bestbuddies.org/get-involved/volunteer/', 'https://www.bestbuddies.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000008', 'e5000000-0000-4000-8000-000000000008', 'Tutor Students Online', 'education', 'UPchieve connects you with students who often do not have access to private tutoring, right when they are stuck on homework. You get a text notification when a student requests help, hop into a virtual classroom, and work through math, science, or writing one on one, or help with college and financial-aid questions. You set your own availability, there is no minimum commitment, and your hours are tracked so they can count toward service requirements.', array['no experience needed', 'counts for school hours'], 14, true, true, true, 'Flexible', 'https://app.upchieve.org/sign-up/volunteer/account', 'https://app.upchieve.org/sign-up/volunteer/account', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000009', 'e5000000-0000-4000-8000-000000000009', 'Tutor a K-12 Student', 'education', 'Learn To Be matches you with a student who needs steady support in a subject you know well, then gives you the tools and training to help them week after week. Sessions happen in an online classroom on a schedule you set with your student, and consistency is what makes the difference. It is a rewarding way to build a mentoring relationship and rack up meaningful, verifiable service hours.', array['recurring', 'counts for school hours'], 13, true, true, true, '1 hr / week', 'https://www.learntobe.org/volunteers', 'https://www.learntobe.org/volunteers', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000010', 'e5000000-0000-4000-8000-000000000010', 'Train as a Crisis Counselor', 'medicine', 'Crisis Text Line volunteers support people through anxiety, depression, self-harm, and moments of real crisis, all over text message. You receive around 30 hours of world-class training before ever taking a conversation, and a supervisor backs you up on every shift. This is a serious commitment of roughly 4 hours a week, and it is one of the most meaningful ways to help that exists.', array['training provided', 'recurring'], 18, true, true, true, '4 hrs / week', 'https://www.crisistextline.org/become-a-volunteer/', 'https://www.crisistextline.org/become-a-volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000011', 'e5000000-0000-4000-8000-000000000011', 'Lend Your Eyes', 'community', 'When someone who is blind or low-vision needs a quick pair of eyes, Be My Eyes rings available volunteers around the world, and whoever answers first hops on a short video call. You might read a food label, check an expiration date, describe a photo, or help someone find something they dropped. Calls take just a few minutes, come only when you are free, and millions of volunteers already share the load.', array['no experience needed', 'one-time'], 17, true, true, true, 'A few min', 'https://www.bemyeyes.com/become-a-volunteer', 'https://www.bemyeyes.com/become-a-volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000012', 'e5000000-0000-4000-8000-000000000012', 'Translate for Humanitarian Aid', 'community', 'When disasters and health crises strike, information has to reach people in a language they actually understand, and that is where this community of volunteer linguists comes in. If you are fluent in more than one language you can translate health guidance, crisis alerts, and education materials for relief organizations operating in over 200 languages. Work is remote and flexible, and every translation can genuinely help keep people safe.', array['recurring'], 18, true, true, true, 'Flexible', 'https://translatorswithoutborders.org/volunteer/', 'https://translatorswithoutborders.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000013', 'e5000000-0000-4000-8000-000000000013', 'Volunteer Online for the UN', 'community', 'Through the UN Online Volunteering service you can support development organizations anywhere in the world without leaving home. Assignments range from writing and research to graphic design, translation, data analysis, and mentoring, and they plug directly into projects working on poverty, health, education, and human rights. It is a standout way for college-age volunteers to gain real experience while contributing to the UN Sustainable Development Goals.', array['leadership role'], 18, true, true, true, 'Flexible', 'https://www.onlinevolunteering.org', 'https://www.onlinevolunteering.org', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000014', 'e5000000-0000-4000-8000-000000000014', 'Support LGBTQ Youth', 'medicine', 'The Trevor Project provides 24/7 crisis support to LGBTQ young people who may have nowhere else to turn. As a trained digital crisis counselor you support youth over chat and text, and the organization provides thorough training and ongoing supervision before and during your shifts. It is a serious ongoing commitment for adult volunteers, and the impact on a young person in crisis can be life-saving.', array['training provided', 'recurring'], 18, true, true, true, '4 hrs / week', 'https://www.thetrevorproject.org/volunteer/', 'https://www.thetrevorproject.org/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000015', 'e5000000-0000-4000-8000-000000000015', 'Help Families at RMHC', 'medicine', 'When a child is seriously ill, Ronald McDonald House gives their family a warm place to stay just steps from the hospital, and volunteers make that house feel like home. You might cook and serve a family meal, welcome guests at the front desk, organize activities for siblings, or help run fundraising events. Roles and age minimums vary by local chapter, and groups are often welcome.', array['good for crews'], 14, false, false, true, '2-3 hrs / shift', 'https://www.rmhc.org/get-involved', 'https://www.rmhc.org/get-involved', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000016', 'e5000000-0000-4000-8000-000000000016', 'Volunteer at Special Olympics', 'sports', 'Special Olympics puts on training and competitions for athletes with intellectual disabilities, and volunteers make every event possible. You can coach a sport, help run competition day, hand out medals, cheer from the sidelines, or support school-based Unified programs where athletes and partners play together. Roles suit all ages, many are one-day commitments, and the energy at these events is unforgettable.', array['good for crews'], 12, false, false, true, 'Half day', 'https://www.specialolympics.org/ways-to-get-involved/volunteer', 'https://www.specialolympics.org/ways-to-get-involved/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000017', 'e5000000-0000-4000-8000-000000000017', 'Advocate for Animals', 'animals', 'The Humane Society tackles animal welfare on a national scale, from puppy mills and wildlife protection to farm-animal welfare and disaster rescue. Volunteers power that work through advocacy, phone and text banking for animal-protection laws, event support, and helping spread the word online. If you care about animals and want your voice to influence real policy, this is a flexible way to help.', array['recurring'], 16, false, false, true, 'Flexible', 'https://www.humanesociety.org/volunteer', 'https://www.humanesociety.org/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000018', 'e5000000-0000-4000-8000-000000000018', 'Volunteer in a National Park', 'environment', 'The Volunteers-In-Parks program invites you to help protect the places that belong to all of us. Depending on the park you might maintain trails, restore habitat, greet and guide visitors, assist at a visitor center, or support citizen-science and conservation projects. Opportunities range from a single day of trail work to ongoing seasonal roles, and many parks welcome families and groups.', array['outdoors', 'good for crews'], 16, false, false, true, 'Half day', 'https://www.nps.gov/getinvolved/volunteer.htm', 'https://www.nps.gov/getinvolved/volunteer.htm', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000019', 'e5000000-0000-4000-8000-000000000019', 'Write to Troops and Veterans', 'veterans', 'Operation Gratitude lets anyone say thank you to the people who serve, no matter where you are. The simplest way to help is writing heartfelt letters of appreciation to deployed troops, veterans, and first responders, which get included in care packages shipped nationwide. It is an all-ages activity you can do solo, with a club, or as a family, and every letter genuinely brightens someone day.', array['no experience needed', 'one-time'], 0, true, true, true, '1 hr', 'https://www.operationgratitude.com/volunteer/', 'https://www.operationgratitude.com/volunteer/', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000020', 'e5000000-0000-4000-8000-000000000020', 'Join a Youth Campaign', 'community', 'DoSomething runs volunteer campaigns designed by and for young people on issues like the environment, mental health, education, and equality. Most campaigns can be done right from your phone, whether that is collecting supplies, spreading awareness, or taking a concrete action in your community. Many campaigns also enter you into scholarship drawings, making it a smart way to do good and get rewarded.', array['no experience needed', 'counts for school hours'], 13, true, true, true, 'Flexible', 'https://www.dosomething.org', 'https://www.dosomething.org', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000021', 'e5000000-0000-4000-8000-000000000021', 'Coach or Cheer with GOTR', 'sports', 'Girls on the Run combines running with lessons that help girls build confidence, kindness, and decision-making skills. Volunteers can coach a team over a season, run alongside a girl as a race-day buddy, or help organize community 5K events. Coaching is the most rewarding role and no running expertise is required, just enthusiasm and a willingness to be a positive role model.', array['recurring'], 14, false, false, true, '2 hrs / week', 'https://www.girlsontherun.org/volunteer', 'https://www.girlsontherun.org/volunteer', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000022', 'e5000000-0000-4000-8000-000000000022', 'Map Biodiversity', 'environment', 'Every photo you take of a wild plant, animal, or fungus on iNaturalist becomes a data point that scientists use to track biodiversity and climate change. Snap a picture, and the community and its AI help identify the species, adding your observation to a global research database. It turns a walk outside into real citizen science, and it is completely free and beginner-friendly.', array['no experience needed', 'outdoors'], 13, true, true, true, 'Flexible', 'https://www.inaturalist.org', 'https://www.inaturalist.org', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000023', 'e5000000-0000-4000-8000-000000000023', 'Translate for Refugees', 'community', 'Language barriers can keep refugees and immigrants from getting medical care, legal help, or safety information. Tarjimly matches you in real time with someone who needs translation in a language you speak, right through the app, for a single conversation at a time. Sessions are short and on-demand, and being fluent in a second language suddenly becomes a way to change someone life.', array['recurring'], 16, true, true, true, 'A few min', 'https://www.tarjimly.org/get-involved', 'https://www.tarjimly.org/get-involved', '2026-01-01T00:00:00Z', null, null),
  ('e6000000-0000-4000-8000-000000000024', 'e5000000-0000-4000-8000-000000000024', 'Sort Food in Atlanta', 'food', 'The Atlanta Community Food Bank distributes tens of millions of meals a year, and its Product Rescue Center depends on volunteers to make that happen. Volunteers sort, inspect, and box donated groceries so they can go out to partner pantries across metro Atlanta and north Georgia. Shifts are a couple of hours, welcoming to school and club groups, and a great local option for service hours.', array['good for crews', 'counts for school hours'], 14, false, false, true, '2.5 hrs / shift', 'https://www.acfb.org/volunteer/', 'https://www.acfb.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e6000000-0000-4000-8000-000000000025', 'e5000000-0000-4000-8000-000000000025', 'Help Shelter Animals', 'animals', 'LifeLine operates the Fulton and DeKalb County animal shelters and works to keep them no-kill, which takes a lot of caring hands. Volunteers walk and socialize dogs, spend calming time with cats, help at adoption events, and take photos that help pets find homes faster. It is a rewarding recurring role for local animal lovers, with orientation and training provided.', array['recurring'], 13, false, false, true, '2 hrs / shift', 'https://lifelineanimal.org/volunteer/', 'https://lifelineanimal.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA');
